import React from "react";
import { useSelector } from "react-redux";
import "./Home.css";

const HomeContent = () => {
  const user = useSelector((state) => state.intern.user);

  return (
    <div className="details-box">
      <h2 style={{ textAlign: "center" }}>Taizo Interns</h2>
      <p><strong>Name:</strong> {user.name}</p>
      <p><strong>Intern Type:</strong> {user.internType}</p>
      <p><strong>Duration:</strong> {user.duration}</p>
      <p>
        <strong>Result:</strong> 
        <span style={{ color: "green", fontWeight: "bold" }}> Selected</span>
      </p>
    </div>
  );
};

export default HomeContent;
